<template>
  <div class="song-card" :style="{ background: mainColor }">
    <h2 class="song-name" :style="{ color: textColor }">{{ songData.songName }}</h2>

    <div class="song-cover">
      <img :src="songData.cover" :alt="songData.songName" class="cover-img" />
    </div>

    <div class="difficulty-wrapper">
      <div
        class="diff-item"
        v-for="diff in ['EZ', 'HD', 'IN', 'AT']"
        :key="diff"
      >
        <template v-if="songData[diff]?.old && songData[diff].old !== 0">
          <div class="diff-tag" :style="{ backgroundColor: songData[diff]?.color }">
            {{ diff }}
          </div>
          <div class="diff-numbers">
            <span class="old-val">{{ songData[diff].old.toFixed(1) }}</span>
            <span class="arrow">↓</span>
            <span class="new-val">{{ songData[diff].new.toFixed(1) }}</span>
            <span class="diff-val" :style="getDiffColor(songData[diff])">
              {{ getDiffText(songData[diff]) }}
            </span>
          </div>
        </template>
      </div>
    </div>
  </div>
</template>

<script setup>
import { useRouter } from 'vue-router'
const router = useRouter()

const props = defineProps({
  songData: { type: Object, required: true },
  songKey: { type: String, required: true },
  mainColor: { type: String, required: true },
  textColor: { type: String, required: true }
})

const getDiffText = (diff) => {
  const oldVal = Number(diff.old)
  const newVal = Number(diff.new)
  const dif = newVal - oldVal
  return dif > 0 ? `+${dif.toFixed(1)}` : dif.toFixed(1)
}

const getDiffColor = (diff) => {
  const dif = Number(diff.new) - Number(diff.old)
  if (dif > 0) return { color: '#4CD964' }
  if (dif < 0) return { color: '#FF3B30' }
  return { color: '#fff' }
}
</script>

<style scoped>
.song-card {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.1rem;
  padding: 0.16rem;
  box-shadow: 0 0.02rem 0.1rem rgba(0, 0, 0, 0.3);
  box-sizing: border-box;
}

.song-cover {
  width: 95%;
  aspect-ratio: 2048 / 1080;
  flex-shrink: 0;
}
.cover-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.song-name {
  font-size: 0.2rem;
  margin: 0;
  text-align: center;
  flex-shrink: 0;
  white-space: nowrap;
  overflow: hidden;
  max-width: 4rem;
  text-overflow: ellipsis;
  max-height: 0.3rem;
}

.difficulty-wrapper {
  width: 100%;
  display: flex;
  flex-direction: row;
  gap: 0.06rem;
  margin-top: auto;
  flex-shrink: 0;
}

.diff-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.04rem;
}

.diff-tag {
  width: 60%;
  height: 0.28rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
